class OrderFlow(private val nav: NavController) {
    fun onAccountChosen(account: Account, amountValid: Boolean) = when {
        account.isCorporate        -> nav.navigate(R.id.toCorporateAmount)
        amountValid                -> nav.navigate(R.id.toConfirm)
        else                       -> nav.navigate(R.id.toAmount)
    }
}
// The destinations/actions themselves live in res/navigation/order.xml
